class MinStack:
    """A stack that reports its smallest value.

    All operations run in constant time. A second stack tracks the minimum
    after every push so pop() can restore the previous minimum in O(1).
    """

    def __init__(self):
        self._items = []
        self._mins = []

    def push(self, value):
        self._items.append(value)
        if not self._mins or value <= self._mins[-1]:
            self._mins.append(value)

    def pop(self):
        if not self._items:
            raise IndexError("pop from empty stack")
        value = self._items.pop()
        if value == self._mins[-1]:
            self._mins.pop()
        return value

    def top(self):
        if not self._items:
            raise IndexError("top from empty stack")
        return self._items[-1]

    def get_min(self):
        if not self._mins:
            raise ValueError("get_min from empty stack")
        return self._mins[-1]

    def __len__(self):
        return len(self._items)
